import math

def count_divisors(n):
    """Counts the number of positive divisors of n."""
    if n == 1:
        return 1
    count = 0
    # Optimized divisor counting by checking up to sqrt(n)
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def check_condition(k):
    """Checks if d(2k^3) = 2k."""
    n = 2 * (k**3)
    divisors = count_divisors(n)
    required = 2 * k
    return divisors == required, divisors, required

results = {}
limit = 30 # Checking up to 30, given analytical bounds suggest solutions are small

print("k | d(2k^3) | 2k | Match")
print("-" * 30)
for k in range(1, limit + 1):
    match, d, r = check_condition(k)
    results[k] = match
    match_str = "YES" if match else "NO"
    print(f"{k:2} | {d:7} | {r:3} | {match_str}")

print("\nSolutions found in range 1 to", limit, ":", [k for k, match in results.items() if match])
